const patch = "*** Begin Patch
*** Add File: jsconsumer/adversarial_review_test.go
+package jsconsumer
+
+import (
+	"testing"
+	"time"
+)
+
+func TestAdversarialIdleFloorMustNotAgeNewWork(t *testing.T) {
+	r, pub := newTestRetry(t, nil)
+	base := time.Now()
+	now := base
+	r.clock = func() time.Time { return now }
+
+	// A caught-up consumer remains idle well past FloorAge.
+	r.observeFloor(100, base)
+	now = base.Add(DefaultFloorAge + time.Minute)
+
+	// The next message has only just arrived and is on its second attempt. Its
+	// own pin is one ladder rung old, not FloorAge old, so it must keep retrying.
+	msg := deliveredMsg(101, DefaultMinDeliveries)
+	s, err := r.Settle(t.Context(), msg, "transient")
+	if err != nil {
+		t.Fatalf("Settle: %v", err)
+	}
+	if s.Outcome != OutcomeRetried {
+		t.Fatalf("idle floor aged fresh work: settlement=%+v captured=%d", s, len(pub.captured()))
+	}
+}
+
+func TestAdversarialFilteredConsumerUsesConsumerSequence(t *testing.T) {
+	r, pub := newTestRetry(t, nil)
+	armFloor(r, 100, DefaultFloorAge+time.Minute)
+
+	// This is consumer sequence 2, immediately above consumer ack floor 1,
+	// but sparse filtering maps it to stream sequence 200.
+	msg := deliveredMsg(200, DefaultMinDeliveries)
+	msg.Meta.Sequence.Consumer = 2
+	s, err := r.Settle(t.Context(), msg, "transient")
+	if err != nil {
+		t.Fatalf("Settle: %v", err)
+	}
+	if s.Outcome != OutcomeDeadLettered {
+		t.Fatalf("filtered floor blocker was not broken: settlement=%+v captured=%d", s, len(pub.captured()))
+	}
+}
*** End Patch";
