*** Add File: jsconsumer/adversarial_review_test.go
+package jsconsumer
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+
+	"github.com/nats-io/nats-server/v2/server"
+	"github.com/nats-io/nats.go/jetstream"
+
+	"github.com/entireio/go-nuts/backoff"
+)
+
+var _ = server.DEFAULT_PORT
+
+func TestAdversarialFinalDLQFailureIsNotRetried(t *testing.T) {
+	nc, js := runTestEnv(t)
+	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
+		Name: "review_wq", Subjects: []string{"review.wq"}, Retention: jetstream.WorkQueuePolicy,
+	}); err != nil {
+		t.Fatal(err)
+	}
+	pub := &fakeDLQ{err: errors.New("DLQ unavailable")}
+	r, err := NewRetry(RetryConfig{
+		Backoff: backoff.Policy{NakDelay: 10 * time.Millisecond, MaxDeliver: 2},
+		FloorAge: DisableFloorAge, DLQSubject: "review.dlq", Publisher: pub,
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	type result struct {
+		s Settlement
+		e error
+	}
+	results := make(chan result, 4)
+	run, err := Start(t.Context(), nc, Config{
+		Stream: "review_wq", Durable: "review", Name: "review",
+		AckWait: 20 * time.Millisecond, MaxDeliver: 2, Retry: r,
+	}, func(msg jetstream.Msg) {
+		s, e := r.Settle(context.Background(), msg, "transient")
+		results <- result{s, e}
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer run.Stop()
+	if _, err := js.Publish(t.Context(), "review.wq", []byte("work")); err != nil {
+		t.Fatal(err)
+	}
+	for want := 1; want <= 2; want++ {
+		select {
+		case got := <-results:
+			t.Logf("delivery %d: settlement=%+v err=%v", want, got.s, got.e)
+		case <-time.After(time.Second):
+			t.Fatalf("delivery %d did not arrive", want)
+		}
+	}
+	select {
+	case got := <-results:
+		t.Logf("unexpected third delivery: settlement=%+v err=%v", got.s, got.e)
+	case <-time.After(250 * time.Millisecond):
+		cons, err := js.Consumer(t.Context(), "review_wq", "review")
+		if err != nil {
+			t.Fatal(err)
+		}
+		info, err := cons.Info(t.Context())
+		if err != nil {
+			t.Fatal(err)
+		}
+		t.Fatalf("final capture failure reported retried but produced no third delivery; ack_floor=%+v ack_pending=%d redelivered=%d", info.AckFloor, info.NumAckPending, info.NumRedelivered)
+	}
+}
